# Trim solution
class _BaseForm(object):
    def clean(self):
        for field in self.cleaned_data:
            # py2 and py3
            try:
                localbasestring = str
            except NameError:
                # Python 3
                localbasestring = str
            if isinstance(self.cleaned_data[field], localbasestring):
                self.cleaned_data[field] = self.cleaned_data[field].strip()

        return super(_BaseForm, self).clean()


class BaseModelForm(_BaseForm, forms.ModelForm):
    pass


class PowerModelAdmin(admin.ModelAdmin):
    buttons = []
    multi_search = []
    list_select_related = True
    multi_search_query = {}
    queryset_filter = {}
    form = BaseModelForm
    list_report = ()
    list_csv = ()

    def has_change_permission(self, request, obj=None):
        change = get_permission_codename('change', self.opts)  # Alterar
        view = get_permission_codename('view', self.opts)  # Visualizar
        browser = get_permission_codename('browser', self.opts)  # Visualizar listagem
        user = request.user

        if obj:
            return user.has_perm(f'{self.opts.app_label}.{change}') or user.has_perm(f'{self.opts.app_label}.{view}')

        return user.has_perm(f'{self.opts.app_label}.{change}') or user.has_perm(f'{self.opts.app_label}.{browser}')

    def has_readonly_permission(self, request, obj=None):
        change = get_permission_codename('change', self.opts)
        view = get_permission_codename('view', self.opts)
        user = request.user
        if not user.has_perm(f'{self.opts.app_label}.{change}') and user.has_perm(f'{self.opts.app_label}.{view}'):
            return True
        return False

    def _all_fields(self, request, obj=None):
        if self.fields:
            return self.fields
        if self.fieldsets:
            return flatten_fieldsets(self.get_fieldsets(request, obj))
        fields = [field.name for field in self.opts.local_fields]
        if 'id' in fields:
            fields.remove('id')
        return fields

    def get_readonly_fields(self, request, obj=None):
        change_permission = super(PowerModelAdmin, self).has_change_permission(request, obj)
        view = get_permission_codename('view', self.opts)
        if not change_permission and request.user.has_perm(f'{self.opts.app_label}.{view}'):
            return self._all_fields(request, obj)
        return super(PowerModelAdmin, self).get_readonly_fields(request, obj)

    def get_list_display_links(self, request, list_display):
        change = get_permission_codename('change', self.opts)
        view = get_permission_codename('view', self.opts)
        browser = get_permission_codename('browser', self.opts)
        user = request.user
        # Não coloca o link se não tiver permissões de editar ou visualizar
        if not (user.has_perm(f'{self.opts.app_label}.{change})') or user.has_perm(f'{self.opts.app_label}.{view}')) \
                and user.has_perm(f'{self.opts.app_label}.{browser}'):
            return []
        return super(PowerModelAdmin, self).get_list_display_links(request, list_display)

    def get_list_csv(self, request):
        if getattr(self, 'list_csv', None) and len(self.list_csv) > 0:
            return self.list_csv
        return self.get_list_display(request)

    def get_list_report(self, request):
        if getattr(self, 'list_report', None):
            return self.list_report
        return self.get_list_display(request)

    def get_header_report(self, request):
        if getattr(self, 'header_report', None):
            return self.header_report
        return '<h1>Listagem de %s</h1>' % self.opts.model._meta.verbose_name_plural.capitalize()

    def get_actions(self, request):
        actions = super(PowerModelAdmin, self).get_actions(request)

        # Exportação do csv
        export_as_csv = export_as_csv_action(fields=self.get_list_csv(request))
        actions['export_as_csv'] = (export_as_csv, 'export_as_csv', export_as_csv.short_description)

        # Report
        report = report_action(fields=self.get_list_report(request), title=self.get_header_report(request))
        actions['report'] = (report, 'report', report.short_description)

        # Ajustes no log do action delete_selected
        # actions['delete_selected'] = (delete_selected, 'delete_selected', delete_selected.short_description)
        return actions

    def get_admin_base_path(self):
        """Retorna a url base do admin"""
        return reverse(f'admin:{self.model._meta.app_label}_{self.model._meta.model_name}_changelist')

    def get_helplink_button(self):
        base_url = self.get_admin_base_path()
        try:
            helplink = HelpLink.objects.get(url_source=base_url)
            return PowerButton(
                url=helplink.url_help, label='Ajuda',
                attrs={'class': 'historylink', 'target': '_blank', 'rel': 'noopener noreferrer'}
            )
        except HelpLink.DoesNotExist:
            return None

    def render_change_form(self, request, context, add=False, change=False, form_url='', obj=None):
        # Verifica se a tela é readonly
        if self.has_readonly_permission(request, obj):
            readonly = True
        else:
            readonly = False
            fields = []
            for field in list(flatten_fieldsets(self.get_fieldsets(request, obj))):
                if isinstance(field, str):
                    fields.append(field)
                else:
                    fields += field

            readonly_fields = self.get_readonly_fields(request, obj)
            if set(fields) == set(readonly_fields).intersection(set(fields)):
                readonly = True

            for inline in context['inline_admin_formsets']:
                if set(flatten_fieldsets(inline.fieldsets)) != set(inline.readonly_fields).intersection(
                        set(flatten_fieldsets(inline.fieldsets))):
                    readonly = False

        object_id = obj.pk if obj else obj
        buttons = self.get_buttons(request, object_id)

        context.update({
            'buttons': buttons,
            'readonly': readonly,
        })
        return super(PowerModelAdmin, self).render_change_form(request, context, add, change, form_url, obj)

    def log_deletion(self, request, object, object_repr):
        """
        Log that an object will be deleted. Note that this method must be called before the deletion.
        The default implementation creates an admin LogEntry object.
        """
        from django.contrib.admin.models import LogEntry, DELETION
        return LogEntry.objects.log_action(
            user_id=request.user.pk,
            content_type_id=get_content_type_for_model(object).pk,
            object_id=object.pk,
            object_repr=object_repr,
            action_flag=DELETION,
            change_message='Deletado.'
        )

    def log_change(self, request, object, message):
        """
        Log that an object has been successfully changed.
        The default implementation creates an admin LogEntry object.
        """
        from django.contrib.admin.models import LogEntry, CHANGE
        if message:
            return LogEntry.objects.log_action(
                user_id=request.user.pk,
                content_type_id=get_content_type_for_model(object).pk,
                object_id=object.pk,
                object_repr=force_text(object),
                action_flag=CHANGE,
                change_message=message,
            )

    def construct_change_message(self, request, form, formsets, *args, **kwargs):
        """Construct a change message from a changed object."""
        change_message = []
        if form.changed_data:
            try:
                if args[0]:
                    change_message = f'Adicionado {form.instance}'
                else:
                    for changed_field in form.changed_data:
                        change_message.append(
                            f'[{changed_field}] de {form.initial[changed_field]} para '
                            f'{form.cleaned_data[changed_field]}'
                        )

                    change_message = 'Modificado %s.' % ', '.join(change_message)

            except Exception:
                return super(PowerModelAdmin, self).construct_change_message(request, form, formsets, *args, **kwargs)

        return change_message

    def button_view_dispatcher(self, request, object_id, command):
        obj = self.model._default_manager.get(pk=object_id)
        return getattr(self, command)(request, obj) or HttpResponseRedirect(request.META['HTTP_REFERER'])

    def related_lookup(self, request):
        data = {}
        if request.method == 'GET':
            if request.GET.get('object_id'):
                try:
                    obj = self.get_queryset(request).get(pk=request.GET.get('object_id'))
                    data = {"value": obj.pk, "label": "%s" % obj}
                except Exception:
                    pass
        return HttpResponse(json.dumps(data), content_type='application/javascript')

    def get_urls(self):
        opts = self.model._meta
        buttons_urls = [
            url(r'^(\d+)/(%s)/$' % but.flag, self.wrap(self.button_view_dispatcher)) for but in self.buttons
        ]
        buttons_urls.append(url(r'^lookup/related/$', self.wrap(self.related_lookup),
                                name="%s_%s_related_lookup" % (opts.app_label, opts.object_name.lower())))
        return buttons_urls + super(PowerModelAdmin, self).get_urls()

    def wrap(self, view):
        from functools import update_wrapper

        def wrapper(*args, **kwargs):
            return self.admin_site.admin_view(view)(*args, **kwargs)

        return update_wrapper(wrapper, view)

    def get_buttons(self, request, object_id=None):
        buttons = [b for b in self.buttons if b.visible]

        help_button = self.get_helplink_button()
        if help_button:
            buttons.append(help_button)

        return buttons

    def get_multi_search_fields(self, request):
        multi_search_fields = []

        for field_opts in self.multi_search:
            attributes = {
                'size': '40',
            }

            if len(field_opts) == 4:
                attributes.update(field_opts[3])

            multi_search_fields.append({
                'name': field_opts[0],
                'label': field_opts[1],
                'value': request.GET.get(field_opts[0], ''),
                'attributes': ' '.join(['%s="%s"' % (k, v) for k, v in attributes.items()]),
            })

        return multi_search_fields

    def get_changelist(self, request, **kwargs):
        from .views import PowerChangeList
        return PowerChangeList

    def changelist_view(self, request, extra_context=None):
        extra_context = extra_context or {}
        data = self.date_hierarchy or ''
        new_request = QueryDict.copy(request.GET)
        is_true = True
        for c, item in request.GET.items():
            if str(c).startswith(data):
                if item == '':
                    del new_request[c]
                elif is_true:
                    extra_context['start_date'] = item
                    is_true = False
                else:
                    extra_context['end_date'] = item

        request.GET = new_request

        admin_old_url = None
        if POWERADMIN_LOG_ADMIN_URL:
            try:
                c_url = resolve(request.path_info)
                if c_url.namespace:
                    url_name = '%s:%s' % (c_url.namespace, c_url.url_name)
                else:
                    url_name = '%s' % c_url.url_name
                admin_config = UserAdminConfig.objects.filter(user=request.user, url_name=url_name)[0]
                admin_old_url = admin_config.url_full_path
                admin_config.url_name = url_name
                admin_config.url_full_path = request.get_full_path()
                admin_config.save()
            except IndexError:
                admin_old_url = None
                UserAdminConfig.objects.create(
                    user=request.user,
                    url_name=url_name,
                    url_full_path=request.get_full_path(),
                )

            if admin_old_url == request.get_full_path():
                admin_old_url = None

        extra_context['admin_old_url'] = admin_old_url

        buttons = self.get_buttons(request, None)

        context_data = {
            'buttons': buttons,
            'multi_search': True,
            'admin_old_url': admin_old_url,
        }
        extra_context.update(context_data)
        return super(PowerModelAdmin, self).changelist_view(request, extra_context)

    def get_search_results(self, request, queryset, search_term):
        """
        Return a tuple containing a queryset to implement the search
        and a boolean indicating if the results may contain duplicates.
        """

        # Apply keyword searches.
        def construct_search(field_name):
            if field_name.startswith('^'):
                return "%s__istartswith" % field_name[1:]
            elif field_name.startswith('='):
                return "%s__iexact" % field_name[1:]
            elif field_name.startswith('@'):
                return "%s__search" % field_name[1:]
            # Use field_name if it includes a lookup.
            opts = queryset.model._meta
            lookup_fields = field_name.split(LOOKUP_SEP)
            # Go through the fields, following all relations.
            prev_field = None
            for path_part in lookup_fields:
                if path_part == 'pk':
                    path_part = opts.pk.name
                try:
                    field = opts.get_field(path_part)
                except FieldDoesNotExist:
                    # Use valid query lookups.
                    if prev_field and prev_field.get_lookup(path_part):
                        return field_name
                else:
                    prev_field = field
                    if hasattr(field, 'get_path_info'):
                        # Update opts to follow the relation.
                        opts = field.get_path_info()[-1].to_opts
            # Otherwise, use the field with icontains.
            return "%s__icontains" % field_name

        may_have_duplicates = False
        # search_term = str > monta a busca padrão do admin
        # search_term = dict > monta a busca multi_search
        if isinstance(search_term, dict):
            for k_query, query in search_term.items():
                fields = None

                for k, l, f in self.multi_search:
                    if k_query == k:
                        fields = f
                        break

                if fields and query:
                    orm_lookups = [construct_search(str(field))
                                   for field in fields]
                    for bit in query.split():
                        or_queries = [models.Q(**{orm_lookup: bit}) for orm_lookup in orm_lookups]
                        queryset = queryset.filter(reduce(operator.or_, or_queries))
                    if not may_have_duplicates:
                        for search_spec in orm_lookups:
                            if lookup_needs_distinct(self.opts, search_spec):
                                may_have_duplicates = True
                                break
        else:
            search_fields = self.get_search_fields(request)
            if search_fields and search_term:
                orm_lookups = [construct_search(str(search_field))
                               for search_field in search_fields]
                for bit in smart_split(search_term):
                    if bit.startswith(('"', "'")) and bit[0] == bit[-1]:
                        bit = unescape_string_literal(bit)
                    or_queries = [models.Q(**{orm_lookup: bit})
                                  for orm_lookup in orm_lookups]
                    queryset = queryset.filter(reduce(operator.or_, or_queries))
                may_have_duplicates |= any(
                    lookup_needs_distinct(self.opts, search_spec)
                    for search_spec in orm_lookups
                )
        return queryset, may_have_duplicates


class PowerButton(object):
    flag = ''  # Usado para URLs fixas do botao, como na versao anterior
    url = ''  # Usado para informar diretamente a URL e assim permitir qualquer URL
    visible = True
    label = 'Label'
    attrs = {'class': 'historylink', }

    def __init__(self, **kwargs):
        for k, v in kwargs.items():
            setattr(self, k, v)

    def get_url(self):
        return self.url or (self.flag + '/')


class PowerInlineModelAdmin(InlineModelAdmin):

    def has_change_permission(self, request, obj=None):
        change_permission = super(PowerInlineModelAdmin, self).has_change_permission(request, obj)  # Alterar
        view = get_permission_codename('view', self.opts)  # Visualizar
        browser = get_permission_codename('browser', self.opts)  # Visualizar listagem
        if obj:
            return change_permission or request.user.has_perm(f'{self.opts.app_label}.{view}')
        return change_permission or request.user.has_perm(f'{self.opts.app_label}.{browser}')

    def _all_fields(self, request, obj=None):
        if self.fields:
            return self.fields
        if self.fieldsets:
            return flatten_fieldsets(self.get_fieldsets(request, obj))
        fields = [field.name for field in self.opts.local_fields]
        if 'id' in fields:
            fields.remove('id')
        return fields

    def get_readonly_fields(self, request, obj=None):
        change_permission = super(PowerInlineModelAdmin, self).has_change_permission(request, obj)
        view = get_permission_codename('view', self.opts)
        if not change_permission and request.user.has_perm(f'{self.opts.app_label}.{view}'):
            return self._all_fields(request, obj)
        return super(PowerInlineModelAdmin, self).get_readonly_fields(request, obj)


class PowerStackedInline(PowerInlineModelAdmin):
    template = 'admin/edit_inline/stacked.html'


class PowerTabularInline(PowerInlineModelAdmin):
    template = 'admin/edit_inline/tabular.html'


class PowerReadOnlyAdmin(PowerModelAdmin):
    """Provides a read-only view of a model in Django admin."""
    readonly_fields = []

    def has_readonly_permission(self, request, obj=None):
        return not request.user.is_superuser

    def get_actions(self, request):
        actions = super().get_actions(request)
        if 'delete_selected' in actions and not request.user.is_superuser:
            del actions['delete_selected']
        return actions

    def get_readonly_fields(self, request, obj=None):
        if request.user.is_superuser:
            return super().get_readonly_fields(request, obj)

        return list(self.readonly_fields) + [field.name for field in obj._meta.fields] + [field.name for field in
                                                                                          obj._meta.many_to_many]

    def has_delete_permission(self, request, obj=None):
        return request.user.is_superuser

    def has_add_permission(self, request):
        return request.user.is_superuser

    def get_inline_instances(self, request, obj=None):
        if not request.user.is_superuser:
            for inline in self.inlines:
                inline.can_delete = False

        return super(PowerReadOnlyAdmin, self).get_inline_instances(request, obj)


@admin.register(HelpLink)
class HelpLinkAdmin(PowerModelAdmin):
    list_display = ['url_source', 'url_help']
    search_fields = ['url_source', 'url_help']
    form = HelpLinkForm
